fn groundDepthAt(wp: vec2<f32>) -> f32 {
    let u = shadowUniforms;
    let uv = vec2<f32>(wp.x / max(u.uSceneSize.x, 1e-3), wp.y / max(u.uSceneSize.y, 1e-3));
