  uInputSize:vec4<f32>,
  uInputPixel:vec4<f32>,
  uInputClamp:vec4<f32>,
  uOutputFrame:vec4<f32>,
  uGlobalFrame:vec4<f32>,
  uOutputTexture:vec4<f32>,
};

struct BlurUniforms {
  uStrength:f32,
};

@group(0) @binding(0) var<uniform> gfu: GlobalFilterUniforms;
@group(0) @binding(1) var uTexture: texture_2d<f32>;
@group(0) @binding(2) var uSampler : sampler;

@group(1) @binding(0) var<uniform> blurUniforms : BlurUniforms;


struct VSOutput {
    @builtin(position) position: vec4<f32>,
    @location(0) offset0: vec2<f32>,
@location(1) offset1: vec2<f32>,
@location(2) offset2: vec2<f32>,
@location(3) offset3: vec2<f32>,
@location(4) offset4: vec2<f32>,
@location(5) offset5: vec2<f32>,
@location(6) offset6: vec2<f32>,
@location(7) offset7: vec2<f32>,
@location(8) offset8: vec2<f32>,
  };

fn filterVertexPosition(aPosition:vec2<f32>) -> vec4<f32>
{
    var position = aPosition * gfu.uOutputFrame.zw + gfu.uOutputFrame.xy;

    position.x = position.x * (2.0 / gfu.uOutputTexture.x) - 1.0;
    position.y = position.y * (2.0*gfu.uOutputTexture.z / gfu.uOutputTexture.y) - gfu.uOutputTexture.z;

    return vec4(position, 0.0, 1.0);
}

fn filterTextureCoord( aPosition:vec2<f32> ) -> vec2<f32>
{
    return aPosition * (gfu.uOutputFrame.zw * gfu.uInputSize.zw);
}

fn globalTextureCoord( aPosition:vec2<f32> ) -> vec2<f32>
{
  return  (aPosition.xy / gfu.uGlobalFrame.zw) + (gfu.uGlobalFrame.xy / gfu.uGlobalFrame.zw);
}

fn getSize() -> vec2<f32>
{
  return gfu.uGlobalFrame.zw;
}


@vertex
fn mainVertex(
  @location(0) aPosition : vec2<f32>,
) -> VSOutput {

  let filteredCord = filterTextureCoord(aPosition);

  let pixelStrength = gfu.uInputSize.w * blurUniforms.uStrength;

  return VSOutput(
   filterVertexPosition(aPosition),
    filteredCord + vec2(0.0, -4 * pixelStrength),
filteredCord + vec2(0.0, -3 * pixelStrength),
filteredCord + vec2(0.0, -2 * pixelStrength),
filteredCord + vec2(0.0, -1 * pixelStrength),
filteredCord + vec2(0.0, 0 * pixelStrength),
filteredCord + vec2(0.0, 1 * pixelStrength),
filteredCord + vec2(0.0, 2 * pixelStrength),
filteredCord + vec2(0.0, 3 * pixelStrength),
filteredCord + vec2(0.0, 4 * pixelStrength),
  );
}

@fragment
fn mainFragment(
  @builtin(position) position: vec4<f32>,
  @location(0) offset0: vec2<f32>,
@location(1) offset1: vec2<f32>,
@location(2) offset2: vec2<f32>,
@location(3) offset3: vec2<f32>,
@location(4) offset4: vec2<f32>,
@location(5) offset5: vec2<f32>,
@location(6) offset6: vec2<f32>,
@location(7) offset7: vec2<f32>,
@location(8) offset8: vec2<f32>,
) -> @location(0) vec4<f32> {

    var   finalColor = vec4(0.0);

    finalColor += textureSample(uTexture, uSampler, offset0) * 0.028532;
finalColor += textureSample(uTexture, uSampler, offset1) * 0.067234;
finalColor += textureSample(uTexture, uSampler, offset2) * 0.124009;
finalColor += textureSample(uTexture, uSampler, offset3) * 0.179044;
finalColor += textureSample(uTexture, uSampler, offset4) * 0.20236;
finalColor += textureSample(uTexture, uSampler, offset5) * 0.179044;
finalColor += textureSample(uTexture, uSampler, offset6) * 0.124009;
finalColor += textureSample(uTexture, uSampler, offset7) * 0.067234;
finalColor += textureSample(uTexture, uSampler, offset8) * 0.028532;

    return finalColor;
}

20.head:
struct GlobalFilterUniforms {
  uInputSize: vec4<f32>,
  uInputPixel: vec4<f32>,
  uInputClamp: vec4<f32>,
  uOutputFrame: vec4<f32>,
  uGlobalFrame: vec4<f32>,
  uOutputTexture: vec4<f32>,
};
@group(0) @binding(0) var<uniform> gfu: GlobalFilterUniforms;
@group(0) @binding(1) var uTexture: texture_2d<f32>;
@group(0) @binding(2) var uSampler: sampler;
struct VSOutput {
  @builtin(position) position: vec4<f32>,
  @location(0) uv: vec2<f32>,
};
fn filterVertexPosition(aPosition: vec2<f32>) -> vec4<f32> {
  var p = aPosition * gfu.uOutputFrame.zw + gfu.uOutputFrame.xy;
  p.x = p.x * (2.0 / gfu.uOutputTexture.x) - 1.0;
  p.y = p.y * (2.0 * gfu.uOutputTexture.z / gfu.uOutputTexture.y) - gfu.uOutputTexture.z;
  return vec4(p, 0.0, 1.0);
}
fn filterTextureCoord(aPosition: vec2<f32>) -> vec2<f32> {
  return aPosition * (gfu.uOutputFrame.zw * gfu.uInputSize.zw);
}
@vertex
fn mainVertex(@location(0) aPosition: vec2<f32>) -> VSOutput {
  return VSOutput(filterVertexPosition(aPosition), filterTextureCoord(aPosition));
}

struct CompositeUniforms {
  uMaskX: vec4<f32>,
  uMaskY: vec4<f32>,
  uBodyStrength: f32,
  uCritStrength: f32,
  _pad0: f32,
  _pad1: f32,
};
@group(1) @binding(0) var<uniform> compositeUniforms: CompositeUniforms;
@group(1) @binding(1) var uBodyRaw: texture_2d<f32>;
@group(1) @binding(2) var uBodyRawSampler: sampler;
@group(1) @binding(3) var uBodyBlur: texture_2d<f32>;
@group(1) @binding(4) var uBodyBlurSampler: sampler;
@group(1) @binding(5) var uCritRaw: texture_2d<f32>;
@group(1) @binding(6) var uCritRawSampler: sampler;
@group(1) @binding(7) var uCritBlur: texture_2d<f32>;
@group(1) @binding(8) var uCritBlurSampler: sampler;
@fragment
fn mainFragment(@location(0) uv: vec2<f32>) -> @location(0) vec4<f32> {
  let base = textureSample(uTexture, uSampler, uv);
  let aPos = uv / (gfu.uOutputFrame.zw * gfu.uInputSize.zw);
  let gpos = gfu.uOutputFrame.xy + aPos * gfu.uOutputFrame.zw;
  let muv = vec2<f32>(
      dot(compositeUniforms.uMaskX.xyz, vec3<f32>(gpos, 1.0)),
      dot(compositeUniforms.uMaskY.xyz, vec3<f32>(gpos, 1.0))
  );
  let inArea = step(0.0, muv.x) * step(muv.x, 1.0)
             * step(0.0, muv.y) * step(muv.y, 1.0);
  let bodyRaw = textureSample(uBodyRaw, uBodyRawSampler, muv).a * inArea;
  let bodyBlur = textureSample(uBodyBlur, uBodyBlurSampler, muv).a * inArea;
  let critRaw = textureSample(uCritRaw, uCritRawSampler, muv).a * inArea;
  let critBlur = textureSample(uCritBlur, uCritBlurSampler, muv).a * inArea;
  let shBody = (1.0 - exp(-max(bodyBlur, 0.0) * compositeUniforms.uBodyStrength)) * (1.0 - bodyRaw);
  let shCrit = (1.0 - exp(-max(critBlur, 0.0) * compositeUniforms.uCritStrength)) * (1.0 - critRaw);
  let rgb = base.rgb * (1.0 - shCrit);
  let aoA = max(shBody, shCrit) * (1.0 - base.a);
  return vec4<f32>(rgb, base.a + aoA);
}

21.head:
struct GlobalFilterUniforms {
  uInputSize: vec4<f32>,
  uInputPixel: vec4<f32>,
  uInputClamp: vec4<f32>,
  uOutputFrame: vec4<f32>,
  uGlobalFrame: vec4<f32>,
  uOutputTexture: vec4<f32>,
};
@group(0) @binding(0) var<uniform> gfu: GlobalFilterUniforms;
@group(0) @binding(1) var uTexture: texture_2d<f32>;
@group(0) @binding(2) var uSampler: sampler;

struct WaterUniforms {
  uTime: f32,
  uMurk: f32,
  uDarkness: f32,
  uRain: f32,
  uSigma: vec3<f32>,
  uMinAlpha: f32,
  uUseNormalMap: f32,
  uWaterBottomDepth: f32,
};
@group(1) @binding(0) var<uniform> waterUniforms: WaterUniforms;
@group(1) @binding(1) var uNormalMap: texture_2d<f32>;
@group(1) @binding(2) var uNormalMapSampler: sampler;
@group(1) @binding(3) var uParams: texture_2d<f32>;
@group(1) @binding(4) var uParamsSampler: sampler;

struct VSOutput {
  @builtin(position) position: vec4<f32>,
  @location(0) vTextureCoord: vec2<f32>,
};

fn filterVertexPosition(aPosition: vec2<f32>) -> vec4<f32> {
  var position = aPosition * gfu.uOutputFrame.zw + gfu.uOutputFrame.xy;
  position.x = position.x * (2.0 / gfu.uOutputTexture.x) - 1.0;
  position.y = position.y * (2.0 * gfu.uOutputTexture.z / gfu.uOutputTexture.y) - gfu.uOutputTexture.z;
  return vec4<f32>(position, 0.0, 1.0);
}

fn filterTextureCoord(aPosition: vec2<f32>) -> vec2<f32> {
  return aPosition * (gfu.uOutputFrame.zw * gfu.uInputSize.zw);
}

@vertex
fn mainVertex(@location(0) aPosition: vec2<f32>) -> VSOutput {
  return VSOutput(filterVertexPosition(aPosition), filterTextureCoord(aPosition));
}

@fragment
fn mainFragment(@location(0) vTextureCoord: vec2<f32>) -> @location(0) vec4<f32> {
  let uv = vTextureCoord;
  let uTime = waterUniforms.uTime;
  let uMurk = waterUniforms.uMurk;

  var ripple = vec2<f32>(
    sin(uv.x * 48.0 + uTime * 1.7) * cos(uv.y * 31.0 - uTime * 1.1),
    cos(uv.y * 44.0 + uTime * 1.4) * sin(uv.x * 29.0 + uTime * 0.9)
  ) * 0.012 * (0.35 + uMurk);

  if (waterUniforms.uUseNormalMap > 0.5) {
    let n = textureSample(uNormalMap, uNormalMapSampler, uv * 2.5 + uTime * 0.03).rgb * 2.0 - 1.0;
    ripple += n.xy * 0.018;
  }

  let suv = clamp(uv + ripple, vec2<f32>(0.001), vec2<f32>(0.999));
  let col = textureSample(uTexture, uSampler, suv);

  let pm = textureSample(uParams, uParamsSampler, suv);
  let pMask = step(0.5, pm.b) * pm.a;
  let bgOpticalPath = max(waterUniforms.uWaterBottomDepth * suv.y, 0.0001);
  let entityRelDepth = max(pm.r, 0.0);
  let entityOpticalPath = max(waterUniforms.uWaterBottomDepth * entityRelDepth, 0.0001);
  let depthGrad = mix(bgOpticalPath, entityOpticalPath, pMask);

  let absorb = exp(-waterUniforms.uSigma * depthGrad * (1.2 + uMurk * 2.5));
  var rgb = col.rgb * absorb;

  rgb *= clamp(1.0 - waterUniforms.uDarkness, 0.15, 1.0);

  let fog = uMurk * 0.35 + waterUniforms.uRain * 0.08;
  rgb = mix(rgb, vec3<f32>(0.55, 0.62, 0.72), clamp(fog, 0.0, 0.85));

  let glowAmt = pMask * pm.g;
  rgb += vec3<f32>(0.82, 0.90, 1.0) * glowAmt * 0.48;

  let rainTint = waterUniforms.uRain * 0.22;
  rgb = mix(rgb, vec3<f32>(0.72, 0.78, 0.88), rainTint);

  return vec4<f32>(rgb, max(col.a, waterUniforms.uMinAlpha));
}

22.head:
struct GlobalFilterUniforms {
  uInputSize: vec4<f32>,
  uInputPixel: vec4<f32>,
  uInputClamp: vec4<f32>,
  uOutputFrame: vec4<f32>,
  uGlobalFrame: vec4<f32>,
  uOutputTexture: vec4<f32>,
};
@group(0) @binding(0) var<uniform> gfu: GlobalFilterUniforms;
@group(0) @binding(1) var uTexture: texture_2d<f32>;
@group(0) @binding(2) var uSampler: sampler;

struct ParamUniforms {
  uDepth: f32,
  uGlow: f32,
};
@group(1) @binding(0) var<uniform> paramUniforms: ParamUniforms;

struct VSOutput {
  @builtin(position) position: vec4<f32>,
  @location(0) vTextureCoord: vec2<f32>,
};

fn filterVertexPosition(aPosition: vec2<f32>) -> vec4<f32> {
  var position = aPosition * gfu.uOutputFrame.zw + gfu.uOutputFrame.xy;
  position.x = position.x * (2.0 / gfu.uOutputTexture.x) - 1.0;
  position.y = position.y * (2.0 * gfu.uOutputTexture.z / gfu.uOutputTexture.y) - gfu.uOutputTexture.z;
  return vec4<f32>(position, 0.0, 1.0);
}

fn filterTextureCoord(aPosition: vec2<f32>) -> vec2<f32> {
  return aPosition * (gfu.uOutputFrame.zw * gfu.uInputSize.zw);
}

@vertex
fn mainVertex(@location(0) aPosition: vec2<f32>) -> VSOutput {
  return VSOutput(filterVertexPosition(aPosition), filterTextureCoord(aPosition));
}

@fragment
fn mainFragment(@location(0) vTextureCoord: vec2<f32>) -> @location(0) vec4<f32> {
  let t = textureSample(uTexture, uSampler, vTextureCoord);
  if (t.a < 0.004) {
    discard;
  }
  return vec4<f32>(paramUniforms.uDepth, paramUniforms.uGlow, 1.0, t.a);
}
